int CharacterWorldNpcPhysicalLifecycleV2::method(void* p,WorldNpcObjectMethodV1 m,std::string& e){auto& s=*static_cast<CharacterWorldNpcPhysicalLifecycleV2*>(p);if(m==WorldNpcObjectMethodV1::EnablePhysicalFilter||m==WorldNpcObjectMethodV1::DisablePhysicalFilter){const bool ok=m==WorldNpcObjectMethodV1::EnablePhysicalFilter?s.physical_.enable_filter():s.physical_.disable_filter();if(!ok)e=s.physical_.error();return ok?0:-1;}if(!s.services_.object_method){e="Required actual NPC visibility/CharacterStop producer";return -1;}return s.services_.object_method(s.services_.context,m,e);}
