int CharacterWorldNpcPhysicalLifecycleV2::update_pf(void* p,std::uintptr_t id,const physical::NativeBody* b,const physical::NpcBodyProjection* projection,std::string& e){auto& s=*static_cast<CharacterWorldNpcPhysicalLifecycleV2*>(p);if(id!=s.borrow_.object.identity||b!=&s.physical_.native()||!projection){e="NPC PF tail must borrow the assigned same physical owner";return -1;}std::copy_n(projection->bounds.relative_box,6,s.borrow_.runtime.subobjects.local_bounds);std::copy_n(projection->bounds.absolute_box,6,s.borrow_.runtime.subobjects.absolute_bounds);if(!s.lifecycle_.update_pf()){e=s.lifecycle_.error();return -1;}return 0;}
