 error_.clear();if(initialized_||registered_||!name||borrow_.world.state_borrow(borrow_.object.identity)!=&borrow_.machine.state()||q.properties!=&borrow_.script.property_view()||q.ai!=&borrow_.ai_tables||!borrow_.object_fields.visible_written||borrow_.runtime.object.motion.floor!=~0u||borrow_.runtime.object.user){error_="Required fresh same registered NPC graph, source PF constructor and properties";return false;}
 if(!borrow_.peers.add({&physical_.world_object(),&physical_.native(),borrow_.object.identity,&borrow_.object_fields,nullptr})){error_=borrow_.peers.error();return false;}registered_=true;
 std::copy(borrow_.object.position.begin(),borrow_.object.position.end(),q.position);
