bool CharacterWorldNpcPhysicalLifecycleV2::close(){error_.clear();if(!registered_&&!physical_.native().body)return true;if(!physical_.release()){error_=physical_.error();return false;}if(!lifecycle_.update_pf()){error_=lifecycle_.error();return false;}if(registered_&&!borrow_.peers.remove(physical_.world_object().context)){error_=borrow_.peers.error();return false;}registered_=initialized_=false;return true;}
